def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 613.3312393566755  # OPT_PARAM: {"initial": 613.3312393566755, "min": 550, "max": 750, "type": "float"}
    pipeline_weight = 0.8725487791291741  # OPT_PARAM: {"initial": 0.8725487791291741, "min": 0.5, "max": 0.9, "type": "float"}
    responsiveness = 0.2  # OPT_PARAM: {"initial": 0.2, "min": 0.2, "max": 0.6, "type": "float"}
    demand_adjustment = 0.8780017444562521  # OPT_PARAM: {"initial": 0.8780017444562521, "min": 0.8, "max": 1.1, "type": "float"}

    smoothed_pipeline = sum(p * (responsiveness ** (i+1)) for i, p in enumerate(reversed(pipeline_orders)))
    net_position = on_hand_inventory + pipeline_weight * smoothed_pipeline
    order_amount = max(0, (base_stock - net_position) * demand_adjustment) * responsiveness
    return order_amount
